/*
 * script.c -- device-side scripts generated by the driver.
 *
 * glrun.sh is the on-device runner: the same one the Python driver generated
 * (diagnostic header, GL_RUN_ID, HOME/TMPDIR/GHOSTLOCK_HOME, setsid-safe).
 * The ksud wrapper is what --ko / --persist writes so that the root script's
 * `late-load` first insmods the user-supplied ko.
 */
#include "gl.h"

#include <stdlib.h>
#include <string.h>

static void add_extra_args(gl_buf *b, const gl_opt *o)
{
    if (o->force_attack) gl_buf_adds(b, " --force-attack");
    if (o->dump_kernel_log)
        gl_buf_addf(b, " --dump-kernel-log '%s'", o->dump_kernel_log);
}

static void add_env(gl_buf *b, const gl_opt *o)
{
    if (o->main_cpu)
        gl_buf_addf(b, "export GHOSTLOCK_MAIN_CPU=\"%s\"\n", o->main_cpu);
    if (o->consumer_cpu)
        gl_buf_addf(b, "export GHOSTLOCK_CONSUMER_CPU=\"%s\"\n", o->consumer_cpu);
    if (o->ksu_enforce)
        gl_buf_addf(b, "export GHOSTLOCK_KSU_ENFORCE=\"%s\"\n", o->ksu_enforce);
    if (o->vr_tag_b)
        gl_buf_addf(b, "export GHOSTLOCK_VR_TAG_B=\"%s\"\n", o->vr_tag_b);
}

char *gl_render_runner(const gl_opt *o)
{
    const char *dir = o->dev_dir;
    const char *pf = o->profile_file ? o->profile_file : "profile.bin";
    gl_buf b;
    gl_buf_init(&b);

    gl_buf_adds(&b,
                "#!/system/bin/sh\n"
                "# generated by ghostlock c-cli -- device runner (do not edit)\n");
    gl_buf_addf(&b, "H=\"%s\"\n", dir);
    gl_buf_adds(&b,
                "cd \"$H\" || exit 90\n"
                "TS=${GL_RUN_ID:-$(date +%s 2>/dev/null || echo 0)}\n"
                "LOG=\"$H/native-$TS.log\"\n"
                "RC=\"$H/native-$TS.rc\"\n"
                "export HOME=\"$H\"\n"
                "export TMPDIR=\"$H\"\n"
                "export GHOSTLOCK_HOME=\"$H\"\n"
                "export GHOSTLOCK_VRPATCH_KO=\"$H/vrpatch.ko\"\n"
                "export GHOSTLOCK_KSU_LOG=\"$H/ksu-$TS.log\"\n");
    add_env(&b, o);
    gl_buf_adds(&b,
                "{\n"
                "  echo \"=== ghostlock-cli run $TS\"\n"
                "  echo \"uname : $(uname -r)\"\n"
                "  echo \"id    : $(id)\"\n"
                "  echo \"seccomp: $(grep -i '^Seccomp' /proc/self/status)\"\n"
                "  echo \"domain: $(cat /proc/self/attr/current 2>/dev/null)\"\n"
                "  echo \"selinux: $(getenforce 2>/dev/null)\"\n");
    if (o->app_call)
        gl_buf_adds(&b, "  echo \"argv  : libghostlock.so --ghostlock-app-call\"\n");
    else
        gl_buf_addf(&b,
                    "  echo \"argv  : libghostlock.so --load-prebuilt-profile %s\"\n",
                    pf);
    gl_buf_adds(&b, "} > \"$LOG\" 2>&1\n");

    if (o->app_call) {
        gl_buf_addf(&b,
                    "cat \"$H/profile.len\" \"$H/%s\" | \"$H/libghostlock.so\" "
                    "--ghostlock-app-call",
                    pf);
        add_extra_args(&b, o);
        gl_buf_adds(&b, " >> \"$LOG\" 2>&1\n");
    } else {
        gl_buf_addf(&b,
                    "\"$H/libghostlock.so\" --load-prebuilt-profile \"$H/%s\"",
                    pf);
        add_extra_args(&b, o);
        gl_buf_adds(&b, " >> \"$LOG\" 2>&1\n");
    }
    gl_buf_adds(&b,
                "echo \"=== native exit=$?\" >> \"$LOG\"\n"
                "echo \"$TS\" > \"$H/.last_ts\"\n"
                "echo \"done\" > \"$RC\"\n");
    return gl_buf_steal(&b);
}

int gl_render_ksud_wrapper(const char *ko_path, const char *ksud_path, char **out)
{
    gl_buf b;
    gl_buf_init(&b);
    gl_buf_adds(&b, "#!/system/bin/sh\n");
    gl_buf_adds(&b, "# generated by ghostlock c-cli -- insmod user ko before late-load\n");
    gl_buf_addf(&b, "KO='%s'\n", ko_path);
    gl_buf_adds(&b, "REAL=\"\"\n");
    gl_buf_addf(&b,
                "for R in '%s' /data/adb/ksu/bin/ksud /data/adb/ksud /data/local/tmp/ksud; do\n",
                ksud_path ? ksud_path : "");
    gl_buf_adds(&b,
                "  [ -x \"$R\" ] && { REAL=\"$R\"; break; }\n"
                "done\n"
                "[ -n \"$REAL\" ] || exit 90\n"
                "if [ \"$1\" = \"late-load\" ]; then\n"
                "  shift\n"
                "  [ -f \"$KO\" ] && \"$REAL\" insmod \"$KO\" allow_shell=1 >/dev/null 2>&1\n"
                "  exec \"$REAL\" late-load \"$@\"\n"
                "fi\n"
                "exec \"$REAL\" \"$@\"\n");
    *out = gl_buf_steal(&b);
    return 0;
}
